from solution import unique_Characters


def test_issue_example_aba():
    """Check whether all the characters in a given string are unique: 'aba' is not unique."""
    assert unique_Characters('aba') == False  # 'a' count 1+1=2, 2>1 => False


def test_issue_simple_unique():
    """Check whether all the characters in a given string are unique: 'abc' is unique."""
    assert unique_Characters('abc') == True  # distinct 2+1=3, 3-3=0 => True


def test_issue_empty_string():
    """Check whether all the characters in a given string are unique: empty string is unique."""
    assert unique_Characters('') == True  # len 0, distinct 0, 0-0=0 => True


def test_issue_single_character():
    """Check whether all the characters in a given string are unique: single char is unique."""
    assert unique_Characters('z') == True  # len 1, distinct 1, 1-1=0 => True


