    """Check whether all the characters in a given string are unique: 'abca' repeats first char."""
    assert unique_Characters('abca') == False  # 'a' count 1+1=2, 2>1 => False


def test_issue_case_sensitive():
    """Check whether all the characters in a given string are unique: 'Aa' differs by case."""
    assert unique_Characters('Aa') == True  # distinct 1+1=2, 2-2=0 => True


